void UserAccount::registerRoutes(httplib::Server& svr, std::shared_ptr<AuthenticationManager> auth)
{
    svr.Get("/user_account/following/boards", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUserAccountfollowingboardsGetRequest(req, res, auth);
    });
    svr.Post("/user_account/following/{username}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUserAccountfollowingusernamePostRequest(req, res, auth);
    });
    svr.Get("/user_account/followers", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUserAccountfollowersGetRequest(req, res, auth);
    });
    svr.Get("/user_account/businesses", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUserAccountbusinessesGetRequest(req, res, auth);
    });
    svr.Delete("/user_account/websites", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUserAccountwebsitesDeleteRequest(req, res, auth);
    });
    svr.Get("/user_account/analytics", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUserAccountanalyticsGetRequest(req, res, auth);
    });
    svr.Get("/user_account/analytics/top_pins", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUserAccountanalyticstopPinsGetRequest(req, res, auth);
    });
    svr.Get("/user_account/analytics/top_video_pins", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUserAccountanalyticstopVideoPinsGetRequest(req, res, auth);
    });
    svr.Get("/users/{username}/interests/follow", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUsersusernameinterestsfollowGetRequest(req, res, auth);
    });
    svr.Get("/user_account", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUserAccountGetRequest(req, res, auth);
    });
    svr.Get("/user_account/following", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUserAccountfollowingGetRequest(req, res, auth);
    });
    svr.Get("/user_account/websites", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUserAccountwebsitesGetRequest(req, res, auth);
    });
    svr.Post("/user_account/websites", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUserAccountwebsitesPostRequest(req, res, auth);
    });
    svr.Get("/user_account/websites/verification", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleUserAccountwebsitesverificationGetRequest(req, res, auth);
    });
}

